// 1. Private data:
const _private = new WeakMap();
class Person {
  constructor(name, secret) {
    _private.set(this, { secret });
    this.name = name;
  }
  getSecret() { return _private.get(this).secret; }
}

// 2. Memoize with object key:
const cache = new WeakMap();
function expensiveCalc(obj) {
  if (cache.has(obj)) return cache.get(obj);
  const result = obj.value * 2; // expensive
  cache.set(obj, result);
  return result;
}

// Private data pattern with WeakMap:
const _private = new WeakMap();

class Person {
  constructor(name, age) {
    _private.set(this, { age }); // private, GC'd with instance
    this.name = name;
  }
  getAge() { return _private.get(this).age; }
}

const p = new Person('Alice', 30);
p.getAge();   // 30
p.age;        // undefined — truly private!
